To solve this problem in C++, we need to check if it's possible to rearrange the given sequence into `abc` by performing at most one swap. Here's how you can implement this logic:

```cpp
#include <iostream>
#include <string>

using namespace std;

bool canMakeABC(const string& s) {
    // Count occurrences of 'a', 'b', and 'c'
    int countA = 0, countB = 0, countC = 0;

    for (char ch : s) {
        switch (ch) {
            case 'a':
                ++countA;
                break;
            case 'b':
                ++countB;
                break;
            case 'c':
                ++countC;
                break;
        }
    }

    // Check if there are enough elements to form 'abc'
    if (countA + countB + countC != 3) return false;

    // If all counts are equal, no swaps needed
    if (countA == countB && countB == countC) return true;

    // Otherwise, try swapping pairs until we get 'abc'
    bool swapped = false;
    for (int i = 0; i < s.length() - 1; ++i) {
        if (s[i] != 'a' || s[i+1] != 'b') continue;

        // Swap 'a' and 'b'
        char temp = s[i];
        s[i] = s[i+1];
        s[i+1] = temp;
        swapped = true;
        break;
    }

    if (!swapped) return false;

    // Verify the result
    if (s == "abc") return true;
    else return false;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        string s;
        cin >> s;
        cout << (canMakeABC(s) ? "YES" : "NO") << endl;
    }
    return 0;
}
```

### Explanation:
1. **Count Occurrences**: First, count the occurrences of `'a'`, `'b'`, and `'c'`.
2. **Check Feasibility**: Ensure that there are exactly three characters (`a`, `b`, and `c`) in total.
3. **Equal Counts**: If all counts are equal, then no swaps are necessary, so return `true`.
4. **Swap Pairs**: Try swapping pairs of `'a'` and `'b'`. If successful, verify the final state.
5. **Output Result**: Based on whether the desired arrangement was achieved, print `"YES"` or `"NO"` accordingly.

This approach ensures correctness and efficiency within the constraints provided.

