public void MergeDocuments(string firstDocPath, string secondDocPath, string outputPath)
{
    // Open the first document
    using (var firstDoc = WordprocessingDocument.Open(firstDocPath, true))
    {
        var mainPart = firstDoc.MainDocumentPart;

        // Get the first 2 pages
        var paragraphs = new List<Paragraph>();
        int currentPageNumber = 0;
        foreach (var section in mainPart.Document.Sections)
        {
            if (++currentPageNumber <= 2)
            {
                foreach (var paragraph in section.Body.Elements<Paragraph>())
                {
                    paragraphs.Add(paragraph);
                }
            }
            else break;
        }

        // Copy headers and footers
        var header = mainPart.Header?.Elements<HeaderFooter>().FirstOrDefault();
        var footer = mainPart.Footer?.Elements<HeaderFooter>().FirstOrDefault();

        if (header != null)
        {
            mainPart.Header = new HeaderFooter(header.Style, header.Format, header.Content);
        }

        if (footer != null)
        {
            mainPart.Footer = new HeaderFooter(footer.Style, footer.Format, footer.Content);
        }

        // Copy styles and fonts
        var styles = mainPart.DocumentStyles ?? new StylesPart(mainPart.Document);
        var styleDefinitions = styles.StyleDefinitions ?? new StyleDefinitionsPart(styles);

        foreach (var style in header.Style.Elements<Style>())
        {
            var existingStyle = styleDefinitions.Styles.FirstOrDefault(s => s.Id == style.Id);
            if (existingStyle == null)
            {
                existingStyle = new Style(style.Id, style.Name, style.StyleName, style.StyleClass, style.StyleId, style.StyleFamily, style.StyleType, style.StyleProperties);
                styleDefinitions.Styles.Add(existingStyle);
            }
            foreach (var property in style.StyleProperties.Elements<StyleProperty>())
            {
                switch (property.Name.LocalName)
                {
                    case "Font":
                        existingStyle.Fonts.Add(new Font(property));
                        break;
                    case "FontSize":
