  glUseProgram program;
  let kernel = glCreateComputeShader """
  #version 330 core

  layout(local_size_x = 8, local_size_y = 8) in;

  void main() {
      int x = gl_GlobalInvocationID.x;
      int y = gl_GlobalInvocationID.y;
      vec3 vectorA = vec3(1.0, 2.0, 3.0); // Example vectors
      vec3 vectorB = vec3(4.0, 5.0, 6.0);
