```javascript
// Function to read a CSV file
async function readFileAsCSV(url) {
    try {
        // Fetch the CSV data from the given URL
        const response = await fetch(url);

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        // Get the text content of the response
        const csvData = await response.text();

        // Split the CSV data into lines (each line represents one row)
        const lines = csvData.split('\n');

        // Process each line to extract values based on column headers
        const columns = lines[0].split(','); // Assuming first line is header

        let result = [];

        for (let i = 1; i < lines.length; i++) { // Start from second line (index 1)
            const values = lines[i].split(',');

            // Create an object for each row using the column names as keys
            const row = {};
            for (let j = 0; j < columns.length; j++) {
                row[columns[j]] = values[j];
            }

            result.push(row);
        }

        return result;
    } catch (error) {
        console.error('Error reading CSV:', error);
    }
}

