    }

    JNIEXPORT void JNICALL Java_com_example_ReverbEffect_applyReverb(JNIEnv *env, jobject obj, jlong reverbHandle, jfloatArray inputSamples, jint numSamples) {
        // Apply reverb effect
        jfloat* input = env->GetFloatArrayElements(inputSamples, nullptr);
        float* output = reinterpret_cast<float*>(reverbHandle);

        for (int i = 0; i < numSamples; ++i) {
