```kotlin
import java.net.InetAddress
import java.net.Socket

class PacketFilter(private val destinationIp: String) {

    fun filterPacket(socket: Socket): Boolean {
        try {
            // Get the remote address from the socket
            val remoteAddress = socket.remoteSocketAddress?.address ?: return false

            // Convert InetAddress to string
            val remoteIp = remoteAddress.toString()

            // Check if the destination IP matches
            return remoteIp == destinationIp
        } catch (e: Exception) {
            e.printStackTrace()
            return false
        }
    }

    companion object {
        private const val DESTINATION_IP = "192.168.1.100" // Example destination IP
    }
}

fun main() {
    val filter = PacketFilter(DESTINATION_IP)

    // Simulate a socket connection
    val socket = Socket("example.com", 80)
    println("Is packet filtered? ${filter.filterPacket(socket)}") // Should print true or false depending on the actual network conditions
}
```

