    if (!res) {
        pr_err("Failed to reserve memory at 0x100000\n");
        return -ENOMEM;
    }

    // Map the memory region
    vaddr = ioremap(res->start, PAGE_SIZE);
    if (!vaddr) {
        pr_err("Failed to map memory at 0x100000\n");
        release_resource(res);
        return -ENOMEM;
    }

    // Use the mapped memory here

    // Free the memory when done
    iounmap(vaddr);
    release_resource(res);

    pr_info("Module loaded successfully\n");
    return 0;
}

static void __exit my_module_exit(void)
{
