    <title>Sprite Editor</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            background-color: #f4f4f9;
        }
        canvas {
            border: 1px solid black;
        }
        .controls {
            margin-top: 20px;
        }
        button {
            margin: 5px;
        }
    </style>
</head>
<body>
    <canvas id="spriteCanvas" width="640" height="480"></canvas>
    <div class="controls">
        <button onclick="loadImage()">Load Image</button>
        <button onclick="drawSprite()">Draw Sprite</button>
        <button onclick="saveSprite()">Save Sprite</button>
    </div>

    <script>
        const canvas = document.getElementById('spriteCanvas');
        const ctx = canvas.getContext('2d');

        let imageLoaded = false;
        let imageData = null;

        function loadImage() {
            if (imageLoaded) return;

            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';

            input.onchange = async () => {
                const file = input.files[0];
                if (!file) return;

                const reader = new FileReader();
                reader.onload = async (e) => {
                    const img = new Image();
                    img.src = e.target.result;
                    await img.decode();

                    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                    imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

                    imageLoaded = true;
                };

                reader.readAsDataURL(file);
            };

            input.click();
        }

        function drawSprite() {
            if (!imageLoaded || !imageData) return;

            const x = prompt("Enter X coordinate:");
            const y = prompt("Enter Y coordinate:");
            const width = prompt("Enter Width:");
            const height = prompt("Enter Height:");

            if (!x || !y || !width || !height) return;

            const startX = parseInt(x);
            const startY = parseInt(y);
            const spriteWidth = parseInt(width);
            const spriteHeight = parseInt(height);

            ctx.clearRect(startX, startY, spriteWidth, spriteHeight);
            ctx.drawImage(imageData, startX, startY, spriteWidth, spriteHeight, 0, 0, spriteWidth, spriteHeight);
        }

        function saveSprite() {
            if (!imageLoaded || !imageData) return;

            const blob = new Blob([ctx.canvas.toDataURL()], { type: 'image/png' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'edited_sprite.png';
            link.click();
        }
    </script>
</body>
</html>
```

