library(ggplot2)

# Sample function to generate a scatter plot of mpg vs wt
generate_scatter_plot <- function(data) {
  ggplot(data, aes(x = wt, y = mpg)) +
    geom_point() +
    labs(title = "Miles Per Gallon vs Weight",
         x = "Weight (1000 lbs)",
         y = "Miles Per Gallon") +
    theme_minimal()
