Then, modify your button click handler like this:

```javascript
$(document).ready(function() {
    $('#add_user_button').on('click', function(e) {
        e.preventDefault(); // Prevent default action (like refreshing the page)

        var userName = $('#user_name').val();
        var userKey = 'd2db5ec4-6e7a-11ee-b962-0242ac120002'; // Fixed user key

