### Without jQuery (Vanilla JS)

If you prefer not to use jQuery, here's how you would achieve the same thing:

```javascript
document.addEventListener('DOMContentLoaded', function() {
    document.getElementById('add_user_button').addEventListener('click', function(e) {
        e.preventDefault();

        const userName = document.getElementById('user_name').value;
        const userKey = 'd2db5ec4-6e7a-11ee-b962-0242ac120002'; // Fixed user key

        fetch('/api/users/' + userName + '/devices/' + userKey, {
            method: 'POST'
        })
        .then(response => response.json())
        .then(data => {
            console.log('User added successfully:', data);
            // Optionally update UI after successful addition
        })
        .catch(error => {
            console.error('Error adding user:', error);
        });
    });
});
```

In both cases, ensure that your backend route (`/api/users/<username>/devices/<userkey>`) correctly handles the incoming POST request and returns appropriate responses.

